-- Class notes synopsis batch 15: Jojoba through Licorice

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Jojoba</strong> is an <strong>oilination</strong> herb that helps the skin maintain its pH and nourish the tissues; a good carrier oil for <strong>eczema</strong> preparations alongside sesame and olive oils.$$
WHERE id = 2641;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Juniper</strong> (Juniperus communis) is a <strong>urinary antiseptic</strong> - kills bacteria in the <strong>urinary tract</strong>; used for <strong>chronic bladder and kidney infections</strong>, <strong>edema</strong> from renal failure (atony), <strong>amenorrhea</strong>, <strong>gout</strong>, and <strong>arthritis</strong>. In Navajo tradition, used with <strong>Bayberry root bark</strong> as a tea; juniper berries used as a female contraceptive. Preparation: Blue/Black Seed Cones (Berries) tincture 1:5, 75% alcohol, 20-40 drops; infusion 2-3 oz 3x/day. Used topically for <strong>psoriasis</strong> - possibly as shampoo for scalp psoriasis.$$
WHERE id = 103;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Kava</strong> ('Awa) is one of the few <strong>skeletal muscle relaxants</strong> (rivals <a href="?herb=2624"><strong>Pedicularis</strong></a>); a <strong>nervine</strong>, <strong>sleep aid</strong>, <strong>antispasmodic</strong>, and <strong>hypnotic analgesic</strong> - decreases pain and increases quality of sleep; exact mechanism unknown; won't sedate an unwilling person. Specific for <strong>dental pain</strong> with a numbing quality; good quality kava makes you drool and the mouth feels tingly numb. For <strong>musculoskeletal pain</strong>, <strong>muscle cramps</strong>, and <strong>muscle tension insomnia</strong>; a <strong>sedative/anodyne</strong> for influenza aches and pains. A heart-opening antispasmodic - good for fast-paced city dwellers, smoothing out <strong>social anxiety</strong>; a nervine for dry constitution; useful for <strong>bladder tension</strong> and urinary system support. For <strong>dissociation</strong> during active injury or procedures (e.g., surgeries) - noted in combination with <strong>Ghost Pipe</strong>. Combined with <a href="?herb=137"><strong>Passionflower</strong></a> for insomnia; add <a href="?herb=84"><strong>Chamomile</strong></a> or <a href="?herb=2607"><strong>Spearmint</strong></a> to balance bitterness. Kava oil: antispasmodic for sore muscles, tightness, and pain. <strong>Anodynes can also be sedative - caution with driving.</strong>$$
WHERE id = 138;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Kelp (Laminaria)</strong> (Kombu) supports <strong>digestion</strong> - add to beans to reduce gas; high in <strong>minerals</strong>; useful for <strong>cardiovascular health</strong>. Also very high in <strong>iodine</strong> - potent; a small strip added to broth is usually enough.$$
WHERE id = 2248;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Kola Nut</strong> is a <strong>nervine stimulant</strong> used for <strong>musculoskeletal deficiency</strong> to stimulate blood flow and sympathetic nervous system response - used alongside <a href="?herb=36"><strong>Pasqueflower</strong></a> (Anemone) and <a href="?herb=14"><strong>Panax Ginseng</strong></a>.$$
WHERE id = 615;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Lady's Mantle</strong> is used in a regenerative tea blend alongside <a href="?herb=151"><strong>Horsetail</strong></a>, <a href="?herb=95"><strong>Corn Silk</strong></a>, <a href="?herb=43"><strong>Nettle</strong></a>, <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=2233"><strong>Hibiscus</strong></a>, and <a href="?herb=42"><strong>Red Clover</strong></a> - taken as large daily infusions.$$
WHERE id = 1014;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Lavender</strong> is a <strong>relaxing nervine</strong>, <strong>anti-inflammatory</strong>, <strong>antimicrobial</strong>, <strong>antispasmodic</strong>, <strong>carminative</strong>, and <strong>vulnerary</strong>; described as "all the anti-s" for the <strong>urinary system</strong> - also a <strong>urinary antiseptic</strong> that kills bacteria in the urinary tract. Its differential picture includes <strong>headaches</strong>, anxiety, and insomnia from constant worry - "a hug in a bottle." For <strong>stagnant depression</strong>, grief, and emotional anchoring; an <strong>antidepressant</strong> for mild to moderate depression by lifting the spirits - the type of depression matters for herb selection; for <strong>GI-based depression</strong> with insomnia and headaches. A nervine for anxiety and <strong>anxiety-induced insomnia</strong> - in sleep tincture with <a href="?herb=137"><strong>Passionflower</strong></a>, <a href="?herb=142"><strong>Skullcap</strong></a>, and <a href="?herb=134"><strong>Lemon Balm</strong></a>; in "Sleepy Horsey" tea with <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=13"><strong>Holy Basil</strong></a>, and <a href="?herb=151"><strong>Horsetail</strong></a>; with chamomile at night for fall self-care sleep; a nervine for children's fear, worry, anxiety, and embarrassment. Combined with <a href="?herb=302"><strong>Tea Tree</strong></a> in wet wipes to cover gram positive bacteria (lavender: staph and MRSA) - sidesteps antibiotic resistance; also in Four Thieves Vinegar as antimicrobial; antimicrobial for <strong>sore throat</strong> via salt water gargle. Vulnerary in wound wash alongside <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=85"><strong>Plantain</strong></a>, <a href="?herb=70"><strong>Calendula</strong></a>, <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=2437"><strong>Self Heal</strong></a>, <a href="?herb=88"><strong>Chickweed</strong></a>, and <strong>St John's Wort</strong>; EO applied topically on minor open wounds after cleaning; wound-healing vulnerary for infected wounds alongside <a href="?herb=44"><strong>Yarrow</strong></a>. EO (1-2 drops in 1 T honey) for minor and severe <strong>burns</strong>; EO diluted in light oil (grapeseed, almond) for <strong>sunburn</strong> - <strong>anti-inflammatory</strong>, <strong>emollient</strong>; hydrosol for burns; oil cooling, antiseptic, and relaxing for bites and burns. EO is the only essential oil safe for direct skin application - a disinfectant used both internally and externally. EO massage for <strong>infant colic</strong>; warm baths with lavender oil to relax and ease. A <strong>GI carminative</strong> rich in volatile oils - good taken after a meal; a carminative for <strong>hypochlorhydria</strong>; EO before bed helps nervous system shift gears.$$
WHERE id = 82;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Lemon Balm</strong> (Melissa) is a <strong>cooling</strong>, <strong>nervine</strong>, <strong>carminative</strong>, <strong>antiviral</strong>, and <strong>antidepressant</strong> herb; nutrient-rich, calcium- and magnesium-rich, and alkalizing to the gut - tea is preferred over tincture for calcium absorption. Rich in <strong>rosmarinic acid</strong> and volatile oils (best extracted by cold infusion 4+ hours or covered hot infusion 20 min); degrades quickly even when fresh - old herbs lose their medicine regardless of preparation method; dry carefully as scent dissipates. Influences <strong>GABA</strong> pathways to promote relaxation and nervous system calm; gentle yet powerful - enhances and potentiates other nervine formulas. Used for <strong>anxiety</strong>, restlessness, <strong>insomnia</strong> (including in pregnancy), <strong>PMS</strong>, menarche support, and nervous system support in food sensitivity; a nervine for children's fear, worry, anxiety, and embarrassment. For <strong>depression</strong>: uplifting yet relaxing; a "light-bearing plant" for <strong>seasonal affective disorder (SAD)</strong> and winter depression; for <strong>GI-based depression</strong> (gut-brain axis), moody and lethargic presentation; for <strong>stagnant depression</strong> from grief or feeling stuck; for depression associated with chemical sensitivity; helps with <strong>decision-making difficulties</strong> and emotional processing; an antidepressant for mild to moderate depression - the type of depression matters for herb selection; for the person who can't stop going; great for infection-induced stress. Rosmarinic acid-rich - supports <strong>methylation</strong>, <strong>estrogen metabolism</strong> in <strong>fibroids</strong>; specific for <strong>hyperthyroidism</strong> - calms thyroid response in autoimmune thyroid conditions (used with <a href="?herb=109"><strong>Rosemary</strong></a> and <a href="?herb=2437"><strong>Self Heal</strong></a>); more indicated for hyperthyroidism but no harm in hypothyroidism. Calcium-rich - supports secondary ossification and <strong>bone density</strong>; modulates pain perception; calcium deficiency linked to more painful cycles (dysmenorrhea). A <strong>GI carminative</strong> rich in volatile oils - good taken after a meal; cooling GI tonic for <strong>hyperchlorhydria</strong>; carminative for <strong>hypochlorhydria</strong>; also <strong>antiemetic</strong> for nausea; when nauseous from bitters, use with <a href="?herb=124"><strong>Ginger</strong></a> or <a href="?herb=136"><strong>Catnip</strong></a>; noted as cooling, drying, and relaxing in digestive tincture blend context, and also moistening when indicated for anxiety. Liver connection - calming for emotional processing; for liver excess as mineral-rich herb to buffer blood. Can substitute for <a href="?herb=155"><strong>Red Raspberry</strong></a> as a nutritive herb in dry constitutions - Raspberry Leaf may be too drying for some. For fertility support as a nutritional tea; in blood-building formula for cold constitution with <a href="?herb=1009"><strong>Dong Quai</strong></a>, <a href="?herb=20"><strong>Ashwagandha</strong></a>, <a href="?herb=885"><strong>Alfalfa</strong></a>, <a href="?herb=2238"><strong>White Peony</strong></a>, and <a href="?herb=78"><strong>Licorice</strong></a>. In sleep/nervine formulas: sleep tincture with <a href="?herb=137"><strong>Passionflower</strong></a> and <a href="?herb=142"><strong>Skullcap</strong></a>; stress formula with <a href="?herb=136"><strong>Catnip</strong></a> and <a href="?herb=84"><strong>Chamomile</strong></a>; mildly uplifting nervine trio with <a href="?herb=136"><strong>Catnip</strong></a> and <a href="?herb=13"><strong>Holy Basil</strong></a> as mild antivirals - always cover infusions to trap volatile oils; hot-to-cold infusion with <a href="?herb=178"><strong>Oat Straw</strong></a> (3 pts) and <a href="?herb=13"><strong>Holy Basil</strong></a> (2 pts); in glycerite blend with <a href="?herb=2233"><strong>Hibiscus</strong></a>, <a href="?herb=73"><strong>Hawthorn</strong></a>, and <a href="?herb=16"><strong>Rhodiola</strong></a> for clarity and calmness; in post-menopausal nourishing tea with <a href="?herb=43"><strong>Nettle</strong></a> and <a href="?herb=885"><strong>Alfalfa</strong></a>; in Dandelion-Nettle-Ginger tea for bloating and water retention; in Steady Study morning tea; in fall self-care morning juicing blend with <a href="?herb=43"><strong>Nettle</strong></a> and <a href="?herb=76"><strong>Fennel</strong></a>; as flavonoid addition in traditional African American glycerine syrup (interchangeable with mint); added to <a href="?herb=115"><strong>Mugwort</strong></a> cold infusion to temper bitterness. Rich in vitamins and minerals; excellent seasoning for chicken or fish.$$
WHERE id = 134;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Lemongrass</strong> is a <strong>warming</strong> herb for cold constitution with volatile oils that are calming; aids <strong>digestion</strong> and serves as flavor enhancement. Used in nourishing tea formulas targeting <strong>bone density</strong> and nervous system support (1 part, long overnight infusion).$$
WHERE id = 2636;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Licorice</strong> (Glycyrrhiza glabra) is a <strong>sweet</strong>, <strong>cooling</strong>, <strong>moistening</strong> <strong>adaptogen</strong>, <strong>demulcent</strong>, <strong>anti-inflammatory</strong>, <strong>antispasmodic</strong>, <strong>hepatoprotective</strong>, <strong>immune amphoteric</strong>, and <strong>tonic</strong>; considered a model adaptogen - in TCM almost every formula uses it as a harmonizer; has medicinal influence on every body system. Dose: decoction 1 tsp root:1 cup water; tincture/FE 10-20 drops 3x/day. Adapts cortisol regulation (hypo or hyper), maintains <strong>HPA axis</strong> communication, addresses general exhaustion and debility; steroidal compounds support adrenal function; inositol and saponins improve fat and insulin metabolism; addresses slowing of metabolism with aging and accumulation of adipose tissue; anabolic support for tissue, muscle, and fetal development; influence on every body system. Supports metabolism and regulates blood sugar; reduces testosterone and prolactin; restores menses; with <a href="?herb=2238"><strong>White Peony</strong></a>: normalizes testosterone and reduces prolactin (especially risperidone-elevated); listed as <strong>anabolic stimulant</strong> for female reproductive deficiency, <strong>hormone and HPA axis support</strong> for male reproductive deficiency. Hepatoprotective; liver alterative for hot constitution; bile-stimulating in hepatic/alterative protocol for chemical sensitivity; liver tea formula (supports metabolism, harmonizer, adaptogen). Antispasmodic to the uterus; supports menses; helpful for <strong>fibroids</strong> via estrogen modulation; isoflavone-rich. In Stansbury Hashimoto's formula (with Guggul, <a href="?herb=118"><strong>Bladderwrack</strong></a>, <a href="?herb=14"><strong>Panax Ginseng</strong></a>, <a href="?herb=31"><strong>Blue Flag</strong></a>); in adaptogen/nervine tincture for thyroid/<strong>Hashimoto's</strong> with <a href="?herb=20"><strong>Ashwagandha</strong></a> and <a href="?herb=178"><strong>Milky Oats</strong></a>; in reproductive formula for thyroid with <a href="?herb=2238"><strong>White Peony</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>, <a href="?herb=22"><strong>Burdock</strong></a>, and <a href="?herb=2229"><strong>Gotu Kola</strong></a>; hypolipidemic for thyroid health; with <a href="?herb=109"><strong>Rosemary</strong></a> for anxiety support. PCOS formula: OGR 30ml, Licorice 10ml, <a href="?herb=2238"><strong>White Peony</strong></a> 30ml, <a href="?herb=167"><strong>Cinnamon</strong></a> 20ml, <a href="?herb=2229"><strong>Gotu Kola</strong></a> 30ml; 4ml 2x/day; also in PMOS formula with <a href="?herb=2238"><strong>White Peony</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>, <a href="?herb=2229"><strong>Gotu Kola</strong></a> for extracellular matrix support. Patient hormonal formula (2 tsp 3x/day): Licorice, <a href="?herb=2238"><strong>White Peony</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>, <a href="?herb=190"><strong>Vitex</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>. Inositol-rich tea for PMOS/fertility: <a href="?herb=225"><strong>Astragalus</strong></a>, Licorice, <a href="?herb=42"><strong>Red Clover</strong></a>, <a href="?herb=885"><strong>Alfalfa</strong></a>, <a href="?herb=1547"><strong>Kudzu Root</strong></a>; in FertiliTea with <a href="?herb=225"><strong>Astragalus</strong></a>, <a href="?herb=885"><strong>Alfalfa</strong></a>, <a href="?herb=42"><strong>Red Clover</strong></a>; in blood-building formula for cold constitution with <a href="?herb=1009"><strong>Dong Quai</strong></a>, <a href="?herb=20"><strong>Ashwagandha</strong></a>, <a href="?herb=134"><strong>Lemon Balm</strong></a>, <a href="?herb=885"><strong>Alfalfa</strong></a>, <a href="?herb=2238"><strong>White Peony</strong></a>. Paired with <a href="?herb=167"><strong>Cinnamon</strong></a> for blood sugar formulas. Hay fever terrain preparation through winter (with <a href="?herb=11"><strong>Reishi Mushroom</strong></a> and <a href="?herb=225"><strong>Astragalus</strong></a>) - lessens allergic responses in spring; shifts body from acidic (allergic) toward alkaline. In Buhner's long COVID/stealth viral protocol (covered under <strong>Japanese Knotweed</strong>). A <strong>GI demulcent</strong> - prefer glycerites, honeys, or vinegars over alcohol for GI use; warming and moistening for cold/dry cough (sticky mucus); anti-inflammatory for <strong>asthma</strong> and antispasmodic; for <strong>emphysema</strong>; cools respiratory excess. DGL (deglycyrrhizinated) capsules for gut lining repair - does not cause the blood pressure response. Sweet, mucilaginous - classic throat coat blend herb; cold-water mucilage extraction. Heals <strong>gastric mucosa</strong> (peptic ulcer); upper GI excess: demulcent; cooling GI tonic for <strong>hyperchlorhydria</strong>; stimulates peristalsis for lower GI deficiency (constipative type); moistening herb for constipation; bulk-building for <strong>childhood constipation</strong>; also in bulk-building candy with <a href="?herb=76"><strong>Fennel</strong></a>, <a href="?herb=45"><strong>Marshmallow root</strong></a>, and psyllium seed; in colic tincture (1 part) with <a href="?herb=76"><strong>Fennel</strong></a>, <a href="?herb=55"><strong>Peppermint</strong></a>; in dermatitis formula with <a href="?herb=70"><strong>Calendula</strong></a>, <a href="?herb=1009"><strong>Dong Quai</strong></a>, <a href="?herb=2229"><strong>Gotu Kola</strong></a>. Hepatic support for <strong>rheumatoid arthritis</strong>. Topically for <strong>eczema</strong>: solvent extract used during flares, rotated in and out; wash via decoction - <strong>caution: internal use can cause a flare (worse before better)</strong>. Immune amphoteric; antiviral for influenza; supports adrenals for kidney deficiency; modulates immune system for lymph/immune excess (autoimmune). In Colon Rescue (for pets) with <a href="?herb=92"><strong>Slippery Elm</strong></a>, <a href="?herb=45"><strong>Marshmallow</strong></a>, <a href="?herb=85"><strong>Plantain</strong></a>. <strong>Can raise blood pressure - important safety note; creates water retention; short-term use in sodium-sensitive individuals; be careful with dosage and high blood pressure; caution: may aggravate BP with potassium imbalance.</strong>$$
WHERE id = 78;
